package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime#addMonths
 */
public class MutableDateTime_addMonths_TriageGen1Test {

    @Test
    public void testAddMonths_Positive() {
        // Start at 2023-01-15
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(3);

        assertEquals(2023, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_Negative() {
        // Start at 2023-05-15
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 0, 0, 0);
        dt.addMonths(-2);

        assertEquals(2023, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_Zero() {
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(0);

        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_YearBoundary() {
        // Test transitioning from one year to next
        MutableDateTime dt = new MutableDateTime(2023, 12, 15, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_EndOfMonthAdjustment() {
        // Test month length adjustment (Jan 31 + 1 month -> Feb 28/29)
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        // Joda-Time handles end-of-month overflow by clamping to last day of month
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_LeapYear() {
        // Test leap year handling
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonths_LargeValue() {
        // Test large number of months
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addMonths(24); // 2 years

        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
    }
}
